// Production asset names and cache key are generated by prepare-public.mjs.
const CACHE='school-language-trainer-shell-dev-controls1';
const FILES=['./','./index.html','./bootstrap.js','./app.css','./app.js','./core.js','./demo.js','./cloud.js','./cloud-config.js','./manifest.webmanifest','./icon.svg','./icon-180.png','./icon-192.png','./icon-512.png','./data/en.json','./data/es.json','./flags/gb.svg','./flags/es.svg'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(async cache=>{for(const url of FILES){const response=await fetch(new Request(url,{cache:'reload'}));if(!response.ok)throw Error('Incomplete application release');await cache.put(url,response);}})));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('school-language-trainer-shell-')&&key!==CACHE).map(key=>caches.delete(key))))));
self.addEventListener('fetch',event=>{
  if(event.request.method!=='GET')return;
  const url=new URL(event.request.url);if(url.origin!==self.location.origin||!url.href.startsWith(self.registration.scope))return;
  event.respondWith((async()=>{
    const cache=await caches.open(CACHE);
    if(/\.[a-f0-9]{16}\.(js|css)$/.test(url.pathname)){
      const cached=await cache.match(event.request);if(cached)return cached;
      const response=await fetch(event.request,{cache:'reload'});if(response.ok)await cache.put(event.request,response.clone());return response;
    }
    try{const response=await fetch(event.request,{cache:'no-store'});if(response.ok)await cache.put(event.request,response.clone());return response;}
    catch{const cached=await cache.match(event.request);if(cached)return cached;if(event.request.mode==='navigate'){const index=await cache.match('./index.html');if(index)return index;}return Response.error();}
  })());
});
